package dev.veltraph.client.combat.ghost;

import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class GhostMenuTransitionTest {
    final Object p=new Object(),w=new Object(),c=new Object(),config=new Object();
    final GhostMenuTransition.Scope scope=new GhostMenuTransition.Scope(p,w,c,config,8);
    final GhostMenuTransition.Menu old=new GhostMenuTransition.Menu(new Object(),new Object(),3,1,"Private Ghost Potions 1");
    final GhostMenuTransition.Menu next=new GhostMenuTransition.Menu(new Object(),new Object(),4,1,"Private Ghost Potions 2");
    GhostMenuTransition.Observation o(GhostMenuTransition.Menu m){return new GhostMenuTransition.Observation(scope,m,true,true,false,false,120);}
    GhostMenuTransition owned(){var t=new GhostMenuTransition(scope,1000);t.issue(null,old.title(),false,false,100);assertTrue(t.observe(o(old)));return t;}
    @Test void oldPrefixPageCannotConsumePendingSuccessor(){var t=owned();var r=t.issue(old,"Private Ghost Potions ",true,true,110);assertTrue(t.allows(o(old)));assertTrue(t.observe(o(old)));assertSame(r,t.pending().orElseThrow());assertTrue(t.allows(o(next)));assertTrue(t.observe(o(next)));assertTrue(t.pending().isEmpty());assertSame(next,t.owned());}
    @Test void partialRevisionAndEmptyCursorAreNotPaginationOutcome(){var t=owned();var r=t.issue(old,"Private Ghost Potions ",true,true,110);var partial=new GhostMenuTransition.Menu(old.screen(),old.menu(),3,2,old.title());assertTrue(t.observe(o(partial)));assertSame(r,t.pending().orElseThrow());assertTrue(t.allows(o(next)));}
    @Test void ownedPredictionCanOnlyWaitOnExactOldMenu(){var t=owned();var r=t.issue(old,"Private Ghost Potions ",true,true,110);var prediction=new GhostMenuTransition.Observation(scope,old,true,false,true,false,120);assertTrue(t.allows(prediction));assertTrue(t.observe(prediction));assertSame(r,t.pending().orElseThrow());assertFalse(t.allows(new GhostMenuTransition.Observation(scope,next,true,false,true,false,120)));}
    @Test void unrequestedSamePrefixMenuAndStalePageAreRejected(){var t=owned();assertFalse(t.allows(o(next)));t.issue(old,"Private Ghost Potions ",true,true,110);var samePage=new GhostMenuTransition.Menu(new Object(),new Object(),4,1,old.title());assertFalse(t.allows(o(samePage)));assertFalse(t.allows(o(new GhostMenuTransition.Menu(new Object(),new Object(),3,1,next.title()))));}
    @Test void oldTokenCannotAcknowledgeSupersedingRequest(){var t=owned();var r=t.issue(old,"Private Ghost Potions ",true,true,110);var current=t.issue(old,"Private Ghost Potions ",true,true,111);assertFalse(t.acknowledge(r,o(next)));assertSame(current,t.pending().orElseThrow());assertTrue(t.acknowledge(current,o(next)));assertFalse(t.acknowledge(current,o(next)));}
    @Test void retiredNativeMenuCannotReenterLaterRequest(){var t=owned();t.issue(old,"Private Ghost Potions ",true,true,110);assertTrue(t.observe(o(next)));t.issue(next,"Private Ghost Potions ",true,true,121);assertFalse(t.allows(new GhostMenuTransition.Observation(scope,old,true,true,false,false,122)));}
    @Test void sameMenuRequiresNewAuthoritativeRevisionAndActualTransitionEffect(){var t=owned();var r=t.issue(old,"Private Ghost Potions ",true,true,110);var changed=new GhostMenuTransition.Menu(old.screen(),old.menu(),3,2,next.title());assertFalse(t.allows(o(changed)));assertSame(r,t.pending().orElseThrow());assertTrue(t.observe(new GhostMenuTransition.Observation(scope,changed,true,true,false,true,120)));assertTrue(t.pending().isEmpty());assertEquals(next.title(),t.owned().title());}
    @Test void changedTitleWithoutNewRevisionIsNotAuthoritativeOutcome(){var t=owned();t.issue(old,"Private Ghost Potions ",true,true,110);var changed=new GhostMenuTransition.Menu(old.screen(),old.menu(),3,1,next.title());assertFalse(t.allows(new GhostMenuTransition.Observation(scope,changed,true,true,false,true,120)));}
    @Test void worldConnectionPlayerConfigurationSlotDeathTimeAndCursorGuardsRemain(){var t=owned();t.issue(old,"Private Ghost Potions ",true,true,110);var bad=List.of(new GhostMenuTransition.Scope(new Object(),w,c,config,8),new GhostMenuTransition.Scope(p,new Object(),c,config,8),new GhostMenuTransition.Scope(p,w,new Object(),config,8),new GhostMenuTransition.Scope(p,w,c,new Object(),8),new GhostMenuTransition.Scope(p,w,c,config,7));for(var s:bad)assertFalse(t.allows(new GhostMenuTransition.Observation(s,next,true,true,false,false,120)));assertFalse(t.allows(new GhostMenuTransition.Observation(scope,next,false,true,false,false,120)));assertFalse(t.allows(new GhostMenuTransition.Observation(scope,next,true,false,false,false,120)));assertFalse(t.allows(new GhostMenuTransition.Observation(scope,next,true,true,false,false,109)));assertFalse(t.allows(new GhostMenuTransition.Observation(scope,next,true,true,false,false,1001)));}
    @Test void foreignLabelAndCancelledLifecycleCannotBorrowPrefixRequest(){var t=owned();t.issue(old,"Private Ghost Potions ",true,true,110);assertFalse(t.allows(o(new GhostMenuTransition.Menu(new Object(),new Object(),4,1,"Private foreign"))));t.cancel();assertFalse(t.allows(o(next)));assertThrows(IllegalStateException.class,()->t.issue(null,"Private Ghost Potions ",true,true,120));}
}
